/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define WIFI_TAG "esp_wifi"
#define WIFI_ERR(...)  syslog(LOG_ERR, WIFI_TAG ": " __VA_ARGS__)
#define WIFI_INFO(...) syslog(LOG_INFO, WIFI_TAG ": " __VA_ARGS__)
#define WIFI_DBG(...)  syslog(LOG_DEBUG, WIFI_TAG ": " __VA_ARGS__)

/* esp_hosted SDIO protocol constants */

#define ESP_HOSTED_CHANNEL_CTRL   0
#define ESP_HOSTED_CHANNEL_DATA   1
#define ESP_HOSTED_HEADER_LEN     8

/* Work queue timing */

#define WIFI_POLL_INTERVAL  (MSEC2TICK(10))  /* 10ms poll interval */

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* esp_hosted SDIO packet header */

struct esp_hosted_header_s
{
  uint8_t  channel;    /* 0=control, 1=data */
  uint8_t  reserved;
  uint16_t len;        /* payload length */
  uint16_t offset;     /* offset to payload */
  uint16_t checksum;   /* header checksum */
};

/* Driver private data */

struct esp_wifi_dev_s
{
  struct net_driver_s  netdev;       /* NuttX network device */
  struct work_s        pollwork;     /* Deferred poll work */
  struct sdio_dev_s   *sdio;        /* SDIO device handle */
  bool                 ifup;        /* Interface is up */
  bool                 connected;   /* WiFi connected */
  uint8_t              mac[6];      /* MAC address */
  uint8_t              rxbuf[1600]; /* Receive buffer */
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

/* Network device callbacks */

static int  esp_wifi_ifup(FAR struct net_driver_s *dev);
static int  esp_wifi_ifdown(FAR struct net_driver_s *dev);
static int  esp_wifi_transmit(FAR struct net_driver_s *dev);
static int  esp_wifi_txavail(FAR struct net_driver_s *dev);
#ifdef CONFIG_NETDEV_IOCTL
static int  esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                           unsigned long arg);
#endif

/* Work queue */

static void esp_wifi_poll_work(FAR void *arg);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_wifi_dev_s g_wifi_dev;

/****************************************************************************
 * Private Functions - Network Device Callbacks
 ****************************************************************************/

static int esp_wifi_ifup(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing up WiFi interface\n");

  /* TODO: Send esp_hosted command to ESP32-C6 to start WiFi STA mode */

  priv->ifup = true;

  /* Schedule periodic poll work */

  work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
             priv, WIFI_POLL_INTERVAL);

  return OK;
}

static int esp_wifi_ifdown(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing down WiFi interface\n");

  /* Cancel poll work */

  work_cancel(LPWORK, &priv->pollwork);

  /* TODO: Send esp_hosted command to ESP32-C6 to stop WiFi */

  priv->ifup = false;
  priv->connected = false;

  return OK;
}

static int esp_wifi_transmit(FAR struct net_driver_s *dev)
{
  int ret;

  WIFI_DBG("Transmitting %d bytes\n", dev->d_len);

  /* Encapsulate the packet in esp_hosted SDIO frame and send to C6 */

  ret = esp32p4_sdio_host_send(ESP_HOSTED_CHANNEL_DATA,
                               dev->d_buf, dev->d_len);
  if (ret < 0)
    {
      WIFI_ERR("Failed to send packet: %d\n", ret);
    }

  return ret;
}

static int esp_wifi_txavail(FAR struct net_driver_s *dev)
{
  if (dev->d_buf != NULL)
    {
      return esp_wifi_transmit(dev);
    }

  return OK;
}

#ifdef CONFIG_NETDEV_IOCTL
static int esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                          unsigned long arg)
{
  /* TODO: Handle WiFi-specific ioctls for WAPI tool
   * (scan, connect, disconnect, etc.)
   */

  UNUSED(dev);
  UNUSED(cmd);
  UNUSED(arg);

  return -ENOTTY;
}
#endif

/****************************************************************************
 * Private Functions - Polling / Receive
 ****************************************************************************/

static void esp_wifi_poll_work(FAR void *arg)
{
  FAR struct esp_wifi_dev_s *priv = (FAR struct esp_wifi_dev_s *)arg;
  int ret;
  uint8_t channel;

  if (!priv->ifup)
    {
      return;
    }

  /* Try to receive data from SDIO */

  ret = esp32p4_sdio_host_recv(&channel, priv->rxbuf,
                               sizeof(priv->rxbuf));
  if (ret > 0)
    {
      if (channel == ESP_HOSTED_CHANNEL_DATA)
        {
          /* Pass received packet to the network stack */

          priv->netdev.d_buf = priv->rxbuf;
          priv->netdev.d_len = ret;

#ifdef CONFIG_NET_PKT
          /* When packet sockets are enabled, feed the frame to the tap */

          netdev_packet_input(&priv->netdev);
#else
          /* Process the received packet through ARP/IP */

          arp_input(&priv->netdev);
#endif
        }
      else if (channel == ESP_HOSTED_CHANNEL_CTRL)
        {
          /* Handle control response from ESP32-C6 */

          WIFI_DBG("Received control response (%d bytes)\n", ret);
          /* TODO: Parse control response */
        }
    }

  /* Re-schedule poll work */

  if (priv->ifup)
    {
      work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
                 priv, WIFI_POLL_INTERVAL);
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp32p4_wifi_init
 ****************************************************************************/

int esp32p4_wifi_init(void)
{
  FAR struct esp_wifi_dev_s *priv = &g_wifi_dev;
  int ret;

  WIFI_INFO("Initializing esp_hosted WiFi\n");

  memset(priv, 0, sizeof(*priv));

  /* Step 1: Initialize SDIO host */

  priv->sdio = esp32p4_sdio_host_init();
  if (priv->sdio == NULL)
    {
      WIFI_ERR("Failed to initialize SDIO host\n");
      return -ENODEV;
    }

  /* Step 2: Initialize esp_hosted protocol on SDIO
   * (Handshake with ESP32-C6, get MAC address, etc.)
   */

  /* TODO: Send init command via SDIO to ESP32-C6
   * Receive MAC address and capabilities
   */

  /* Use a default MAC address for now */

  priv->mac[0] = 0x02;  /* Locally administered */
  priv->mac[1] = 0x00;
  priv->mac[2] = 0x00;
  priv->mac[3] = 0x00;
  priv->mac[4] = 0x00;
  priv->mac[5] = 0x01;

  /* Step 3: Register network device */

  priv->netdev.d_ifup    = esp_wifi_ifup;
  priv->netdev.d_ifdown  = esp_wifi_ifdown;
  priv->netdev.d_txavail = esp_wifi_txavail;
#ifdef CONFIG_NETDEV_IOCTL
  priv->netdev.d_ioctl   = esp_wifi_ioctl;
#endif
  priv->netdev.d_private = priv;

  /* Set MAC address */

  memcpy(priv->netdev.d_mac.ether.ether_addr_octet, priv->mac, 6);

  ret = netdev_register(&priv->netdev, NET_LL_IEEE80211);
  if (ret < 0)
    {
      WIFI_ERR("Failed to register network device: %d\n", ret);
      return ret;
    }

  WIFI_INFO("esp_hosted WiFi initialized, device: wlan0\n");
  return OK;
}

