/****************************************************************************
 * boards/risc-v/esp32p4/esp32p4-function-ev-board/src/esp32p4_sdio_host.c
 *
 * SDIO host driver for ESP32-P4 to communicate with ESP32-C6 co-processor
 * via esp_hosted protocol.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/sdio.h>
#include <nuttx/irq.h>
#include <debug.h>
#include <errno.h>
#include <string.h>

#include "esp32p4_sdio_host.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SDIO_HOST_TAG "sdio_host"
#define SDIO_HOST_ERR(...)  syslog(LOG_ERR, SDIO_HOST_TAG ": " __VA_ARGS__)
#define SDIO_HOST_INFO(...) syslog(LOG_INFO, SDIO_HOST_TAG ": " __VA_ARGS__)
#define SDIO_HOST_DBG(...)  syslog(LOG_DEBUG, SDIO_HOST_TAG ": " __VA_ARGS__)

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp_sdio_host_dev_s
{
  struct sdio_dev_s  dev;           /* NuttX SDIO device (must be first) */
  uint8_t            bus_num;       /* SDIO bus number */
  uint32_t           freq;          /* Clock frequency */
  uint8_t            gpio_data_rdy; /* DATA_READY GPIO from C6 */
  bool               initialized;   /* Initialization state */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_sdio_host_dev_s g_sdio_host_dev;

/****************************************************************************
 * Private Functions - NuttX SDIO Interface Stubs
 ****************************************************************************/

static void esp_sdio_reset(FAR struct sdio_dev_s *dev)
{
  UNUSED(dev);
