}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

FAR struct sdio_dev_s *esp32p4_sdio_host_init(void)
{
  struct esp_sdio_host_dev_s *priv = &g_sdio_host_dev;

  SDIO_HOST_INFO("Initializing SDIO host for esp_hosted\n");

  memset(priv, 0, sizeof(*priv));

  /* Set up SDIO device interface callbacks */

  priv->dev.reset          = esp_sdio_reset;
  priv->dev.capabilities   = esp_sdio_capabilities;
  priv->dev.status         = esp_sdio_status;
  priv->dev.widebus        = esp_sdio_widebus;
  priv->dev.clock          = esp_sdio_clock;
  priv->dev.attach         = esp_sdio_attach;
  priv->dev.sendcmd        = esp_sdio_sendcmd;
  priv->dev.recvsetup      = esp_sdio_recvsetup;
  priv->dev.sendsetup      = esp_sdio_sendsetup;
  priv->dev.cancel         = esp_sdio_cancel;
  priv->dev.waitresponse   = esp_sdio_waitresponse;
  priv->dev.recv_r1        = esp_sdio_recv_r1;
  priv->dev.recv_r3        = esp_sdio_recv_r3;
  priv->dev.recv_r5        = esp_sdio_recv_r5;
  priv->dev.recv_r6        = esp_sdio_recv_r6;
  priv->dev.recv_r7        = esp_sdio_recv_r7;
  priv->dev.waitenable     = esp_sdio_waitenable;
  priv->dev.eventwait      = esp_sdio_eventwait;
  priv->dev.callbackenable = esp_sdio_callbackenable;

  /* Read configuration from Kconfig */

  priv->bus_num       = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_BUS;
  priv->freq          = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ;
  priv->gpio_data_rdy = CONFIG_ESP32P4_WIFI_HOSTED_GPIO_DATA_RDY;

  /* TODO: Initialize ESP-IDF SDMMC host driver */

  priv->initialized = true;
  SDIO_HOST_INFO("SDIO host initialized (bus=%d freq=%lu)\n",
                 priv->bus_num, (unsigned long)priv->freq);

  return &priv->dev;
}

int esp32p4_sdio_host_send(uint8_t channel, FAR const uint8_t *data,
                           uint16_t len)
{
  UNUSED(channel);
  UNUSED(data);
  UNUSED(len);
  /* TODO: Send via SDIO */
  return OK;
}

int esp32p4_sdio_host_recv(FAR uint8_t *channel, FAR uint8_t *data,
                           uint16_t len)
{
  UNUSED(channel);
  UNUSED(data);
  UNUSED(len);
  /* TODO: Receive from SDIO */
  return 0;
}

