/****************************************************************************
 * esp32p4_sdio_host.c
 *
 * SDIO host driver for ESP32-P4 communicating with ESP32-C6 co-processor
 * via esp_hosted protocol over SDIO.
 *
 * Uses ESP-IDF SDMMC HAL for hardware access.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <stdio.h>

#include "esp32p4_sdio_host.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define SDIO_TAG "sdio"
#define SDIO_ERR(...)   syslog(LOG_ERR, SDIO_TAG ": " __VA_ARGS__)
#define SDIO_INFO(...)  syslog(LOG_INFO, SDIO_TAG ": " __VA_ARGS__)
#define SDIO_DBG(...)   syslog(LOG_DEBUG, SDIO_TAG ": " __VA_ARGS__)

/* SDIO command definitions */

#define SDIO_CMD_GO_IDLE_STATE      0   /* CMD0  */
#define SDIO_CMD_SEND_OP_COND       5   /* CMD5  */
#define SDIO_CMD_SEND_RELATIVE_ADDR 3   /* CMD3  */
#define SDIO_CMD_SELECT_CARD        7   /* CMD7  */
#define SDIO_CMD_IO_RW_DIRECT      52   /* CMD52 */
#define SDIO_CMD_IO_RW_EXTENDED    53   /* CMD53 */

/* SDIO response types */

#define SDIO_RESP_NONE  0
#define SDIO_RESP_R4    1
#define SDIO_RESP_R6    2

/* CMD52 argument fields */

#define CMD52_FUNC(x)       (((x) & 0x7) << 28)
#define CMD52_BLOCK_MODE    (1 << 27)
#define CMD52_OP_WRITE      (1 << 31)
#define CMD52_RAW           (1 << 27)
#define CMD52_REG_ADDR(x)   (((x) & 0x1FFFF) << 9)

/* CMD53 argument fields */

#define CMD53_FUNC(x)       (((x) & 0x7) << 28)
#define CMD53_BLOCK_MODE    (1 << 27)
#define CMD53_OP_WRITE      (1 << 31)
#define CMD53_REG_ADDR(x)   (((x) & 0x1FFFF) << 9)
#define CMD53_COUNT(x)      (((x) & 0x1FF))

/* SDIO register addresses */

#define SDIO_CCCR_IO_READY   0x02
#define SDIO_CCCR_IO_ENABLE  0x02
#define SDIO_CCCR_IO_ABORT   0x06
#define SDIO_CCCR_BUS_CTRL   0x07
#define SDIO_CCCR_CAPABILITY 0x08

/* esp_hosted SDIO register base for function 1 */

#define ESP_HOSTED_IO_PORT   0x00000

/* Timing */

#define SDIO_INIT_TIMEOUT_MS   1000
#define SDIO_CMD_TIMEOUT_MS    100
#define SDIO_DATA_TIMEOUT_MS   500

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct esp_sdio_host_dev_s
{
  mutex_t             lock;          /* Mutex for thread safety */
  uint8_t             bus_num;       /* SDIO bus number */
  uint32_t           freq;          /* Clock frequency in Hz */
  uint8_t             gpio_data_rdy; /* DATA_READY GPIO from C6 */
  bool               initialized;   /* Initialization state */
  uint16_t           rca;           /* Relative Card Address */
  uint8_t             buffer[2048];  /* Transfer buffer */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_sdio_host_dev_s g_sdio;

/****************************************************************************
 * Private Functions - Low Level SDIO
 ****************************************************************************/

/****************************************************************************
 * Name: sdio_send_cmd
 *
 * Description:
 *   Send an SDIO command and optionally read the response.
 *   Uses direct register access to the ESP32-P4 SDMMC peripheral.
 *
 ****************************************************************************/

static int sdio_send_cmd(uint32_t cmd, uint32_t arg,
                         uint32_t *resp, int resp_type)
{
  volatile uint32_t *cmd_reg  = (volatile uint32_t *)0x50490000;
  volatile uint32_t *arg_reg  = (volatile uint32_t *)0x50490004;
  volatile uint32_t *ctrl_reg = (volatile uint32_t *)0x50490008;
  volatile uint32_t *int_reg  = (volatile uint32_t *)0x50490030;
  volatile uint32_t *rint_reg = (volatile uint32_t *)0x50490034;
  int timeout;

  /* Wait for controller idle */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while ((*ctrl_reg & 0x80000000) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      SDIO_ERR("Controller busy\n");
      return -ETIMEDOUT;
    }

  /* Clear pending interrupts */

  *int_reg = 0xFFFFFFFF;

  /* Set argument */

  *arg_reg = arg;

  /* Build command register value */

  uint32_t cmd_val = cmd & 0x3F;

  /* Set response type */

  switch (resp_type)
    {
      case SDIO_RESP_R4:
      case SDIO_RESP_R6:
        cmd_val |= (1 << 6);  /* Response expected */
        cmd_val |= (1 << 7);  /* Check response CRC */
        break;
      default:
        break;
    }

  cmd_val |= (1 << 13);  /* Wait for data complete */
  cmd_val |= (1 << 10);  /* Send initialization sequence if CMD0 */
  cmd_val |= (1 << 31);  /* Start command */

  *cmd_reg = cmd_val;

  /* Wait for command done */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while (!(*rint_reg & 0x4) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      SDIO_ERR("CMD%lu timeout\n", (unsigned long)cmd);
      return -ETIMEDOUT;
    }

  /* Check for errors */

  if (*rint_reg & 0x2)
    {
      SDIO_ERR("CMD%lu response error\n", (unsigned long)cmd);
      return -EIO;
    }

  if (*rint_reg & 0x100)
    {
      SDIO_ERR("CMD%lu response timeout\n", (unsigned long)cmd);
      return -ETIMEDOUT;
    }

  /* Read response if requested */

  if (resp != NULL && resp_type != SDIO_RESP_NONE)
    {
      /* Response is in RESP0 register (offset 0x30) */

      *resp = *((volatile uint32_t *)0x50490014);
    }

  return OK;
}

/****************************************************************************
 * Name: sdio_cmd52_read
 *
 * Description:
 *   CMD52 - IO Read Direct (single byte)
 *
 ****************************************************************************/

static int sdio_cmd52_read(uint8_t func, uint32_t addr, uint8_t *data)
{
  uint32_t arg;
  uint32_t resp;
  int ret;

  arg = CMD52_FUNC(func) | CMD52_REG_ADDR(addr);

  ret = sdio_send_cmd(SDIO_CMD_IO_RW_DIRECT, arg, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      return ret;
    }

  if (data != NULL)
    {
      *data = (resp >> 8) & 0xFF;
    }

  return OK;
}

/****************************************************************************
 * Name: sdio_cmd52_write
 *
 * Description:
 *   CMD52 - IO Write Direct (single byte)
 *
 ****************************************************************************/

static int sdio_cmd52_write(uint8_t func, uint32_t addr, uint8_t data,
                            uint8_t *resp_data)
{
  uint32_t arg;
  uint32_t resp;
  int ret;

  arg = CMD52_OP_WRITE | CMD52_FUNC(func) | CMD52_REG_ADDR(addr) | data;

  ret = sdio_send_cmd(SDIO_CMD_IO_RW_DIRECT, arg, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      return ret;
    }

  if (resp_data != NULL)
    {
      *resp_data = (resp >> 8) & 0xFF;
    }

  return OK;
}

/****************************************************************************
 * Name: sdio_cmd53_read
 *
 * Description:
 *   CMD53 - IO Read Extended (block transfer)
 *
 ****************************************************************************/

static int sdio_cmd53_read(uint8_t func, uint32_t addr,
                           uint8_t *buf, uint16_t count)
{
  uint32_t arg;
  uint32_t resp;
  int ret;
  int i;

  /* For simplicity, use byte mode (not block mode) */

  arg = CMD53_FUNC(func) | CMD53_REG_ADDR(addr) | CMD53_COUNT(count);

  ret = sdio_send_cmd(SDIO_CMD_IO_RW_EXTENDED, arg, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      return ret;
    }

  /* Read data from FIFO */

  volatile uint32_t *fifo = (volatile uint32_t *)0x50490200;

  for (i = 0; i < (count + 3) / 4; i++)
    {
      uint32_t word = *fifo;
      int j;
      for (j = 0; j < 4 && (i * 4 + j) < count; j++)
        {
          buf[i * 4 + j] = (word >> (j * 8)) & 0xFF;
        }
    }

  return count;
}

/****************************************************************************
 * Name: sdio_cmd53_write
 *
 * Description:
 *   CMD53 - IO Write Extended (block transfer)
 *
 ****************************************************************************/

static int sdio_cmd53_write(uint8_t func, uint32_t addr,
                            const uint8_t *buf, uint16_t count)
{
  uint32_t arg;
  uint32_t resp;
  int ret;
  int i;

  arg = CMD53_OP_WRITE | CMD53_FUNC(func) |
        CMD53_REG_ADDR(addr) | CMD53_COUNT(count);

  /* Write data to FIFO */

  volatile uint32_t *fifo = (volatile uint32_t *)0x50490200;

  for (i = 0; i < (count + 3) / 4; i++)
    {
      uint32_t word = 0;
      int j;
      for (j = 0; j < 4 && (i * 4 + j) < count; j++)
        {
          word |= ((uint32_t)buf[i * 4 + j]) << (j * 8);
        }
      *fifo = word;
    }

  ret = sdio_send_cmd(SDIO_CMD_IO_RW_EXTENDED, arg, &resp, SDIO_RESP_R4);
  if (ret < 0)
    {
      return ret;
    }

  return count;
}

/****************************************************************************
 * Name: sdio_init_hw
 *
 * Description:
 *   Initialize the ESP32-P4 SDMMC hardware for SDIO communication.
 *
 ****************************************************************************/

static int sdio_init_hw(void)
{
  volatile uint32_t *clk_rst_reg;
  int timeout;
  uint32_t resp;
  int ret;

  SDIO_INFO("Initializing SDMMC hardware\n");

  /* Step 1: Enable SDMMC peripheral clock
   * ESP32-P4: HP_SYS_CLKRST.soc_clk_ctrl1.reg_sdmmc_sys_clk_en
   */

  clk_rst_reg = (volatile uint32_t *)0x50116004;
  *clk_rst_reg |= (1 << 12);  /* Enable SDMMC clock */

  /* Step 2: Configure GPIO pins for SDIO2 (GPIO8-15)
   * Use GPIO matrix routing for SDIO2
   */

  /* TODO: Configure GPIO matrix for SDIO2 pins
   * GPIO8  = D3
   * GPIO9  = D2
   * GPIO10 = D1
   * GPIO11 = D0
   * GPIO12 = IO2 (data ready)
   * GPIO13 = RST (reset to C6)
   * GPIO14 = CK  (clock)
   * GPIO15 = CMD (command)
   */

  /* Step 3: Reset the SDMMC controller */

  volatile uint32_t *ctrl = (volatile uint32_t *)0x50490000;
  *ctrl = 0x1;  /* Software reset */
  up_mdelay(10);

  /* Step 4: Set clock to identification mode (400kHz) */

  /* TODO: Configure clock divider for 400kHz */

  /* Step 5: Send CMD0 (GO_IDLE_STATE) */

  ret = sdio_send_cmd(SDIO_CMD_GO_IDLE_STATE, 0, NULL, SDIO_RESP_NONE);
  if (ret < 0)
    {
      SDIO_ERR("CMD0 failed: %d\n", ret);
      return ret;
    }

  up_mdelay(10);

  /* Step 6: Send CMD5 (IO_SEND_OP_COND) to detect SDIO card
   * Repeat until card is ready
   */

  timeout = SDIO_INIT_TIMEOUT_MS;
  while (timeout-- > 0)
    {
      /* CMD5 with arg=0 to query voltage window */

      ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0, &resp, SDIO_RESP_R4);
      if (ret < 0)
        {
          up_mdelay(1);
          continue;
        }

      /* Check if card is ready (bit 31 of R4) */

      if (resp & (1 << 31))
        {
          SDIO_INFO("SDIO card ready, OCR=0x%08lx\n", (unsigned long)resp);
          break;
        }

      /* Send CMD5 with voltage window to power up card */

      ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0x00FF8000,
                          &resp, SDIO_RESP_R4);
      up_mdelay(10);
    }

  if (timeout <= 0)
    {
      SDIO_ERR("SDIO card not ready\n");
      return -ETIMEDOUT;
    }

  /* Step 7: Send CMD3 (SEND_RELATIVE_ADDR) to get RCA */

  ret = sdio_send_cmd(SDIO_CMD_SEND_RELATIVE_ADDR, 0, &resp, SDIO_RESP_R6);
  if (ret < 0)
    {
      SDIO_ERR("CMD3 failed: %d\n", ret);
      return ret;
    }

  g_sdio.rca = (resp >> 16) & 0xFFFF;
  SDIO_INFO("SDIO RCA=0x%04x\n", g_sdio.rca);

  /* Step 8: Send CMD7 (SELECT_CARD) to select the card */

  ret = sdio_send_cmd(SDIO_CMD_SELECT_CARD,
                      ((uint32_t)g_sdio.rca) << 16,
                      &resp, SDIO_RESP_R6);
  if (ret < 0)
    {
      SDIO_ERR("CMD7 failed: %d\n", ret);
      return ret;
    }

  SDIO_INFO("SDIO card selected\n");

  /* Step 9: Enable SDIO function 1 (used by esp_hosted) */

  ret = sdio_cmd52_write(0, SDIO_CCCR_IO_ENABLE, 0x02, NULL);
  if (ret < 0)
    {
      SDIO_ERR("Failed to enable SDIO function 1: %d\n", ret);
      return ret;
    }

  /* Wait for function 1 to be ready */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while (timeout-- > 0)
    {
      uint8_t ready;
      ret = sdio_cmd52_read(0, SDIO_CCCR_IO_READY, &ready);
      if (ret >= 0 && (ready & 0x02))
        {
          SDIO_INFO("SDIO function 1 ready\n");
          break;
        }
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      SDIO_ERR("SDIO function 1 not ready\n");
      return -ETIMEDOUT;
    }

  /* Step 10: Set bus width to 4-bit */

  ret = sdio_cmd52_write(0, SDIO_CCCR_BUS_CTRL, 0x02, NULL);
  if (ret < 0)
    {
      SDIO_ERR("Failed to set 4-bit bus width: %d\n", ret);
      /* Not fatal, continue with 1-bit mode */
    }
  else
    {
      SDIO_INFO("4-bit bus width enabled\n");
    }

  /* Step 11: Increase clock speed to operational frequency */

  /* TODO: Set clock to CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ */

  SDIO_INFO("SDIO host initialized successfully\n");
  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp32p4_sdio_host_init
 ****************************************************************************/

int esp32p4_sdio_host_init(void)
{
  int ret;

  memset(&g_sdio, 0, sizeof(g_sdio));
  nxmutex_init(&g_sdio.lock);

  g_sdio.bus_num       = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_BUS;
  g_sdio.freq          = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ;
  g_sdio.gpio_data_rdy = CONFIG_ESP32P4_WIFI_HOSTED_GPIO_DATA_RDY;

  /* Initialize SDIO hardware */

  ret = sdio_init_hw();
  if (ret < 0)
    {
      SDIO_ERR("SDIO hardware init failed: %d\n", ret);
      return ret;
    }

  g_sdio.initialized = true;
  return OK;
}

/****************************************************************************
 * Name: esp32p4_sdio_host_send
 ****************************************************************************/

int esp32p4_sdio_host_send(uint8_t channel, const uint8_t *data,
                           uint16_t len)
{
  struct esp_hosted_header_s hdr;
  uint8_t *pkt;
  int ret;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  /* Build esp_hosted packet */

  hdr.channel  = channel;
  hdr.reserved = 0;
  hdr.len      = len;
  hdr.offset   = sizeof(hdr);
  hdr.checksum = channel + len;

  /* Copy header + data to buffer */

  pkt = g_sdio.buffer;
  memcpy(pkt, &hdr, sizeof(hdr));
  memcpy(pkt + sizeof(hdr), data, len);

  nxmutex_lock(&g_sdio.lock);

  /* Write to SDIO function 1 */

  ret = sdio_cmd53_write(1, ESP_HOSTED_IO_PORT,
                         pkt, sizeof(hdr) + len);

  nxmutex_unlock(&g_sdio.lock);

  if (ret < 0)
    {
      SDIO_ERR("SDIO send failed: %d\n", ret);
      return ret;
    }

  return OK;
}

/****************************************************************************
 * Name: esp32p4_sdio_host_recv
 ****************************************************************************/

int esp32p4_sdio_host_recv(uint8_t *channel, uint8_t *data,
                           uint16_t max_len)
{
  struct esp_hosted_header_s hdr;
  int ret;
  int pkt_len;

  if (!g_sdio.initialized)
    {
      return -ENODEV;
    }

  nxmutex_lock(&g_sdio.lock);

  /* Read header first (8 bytes) */

  ret = sdio_cmd53_read(1, ESP_HOSTED_IO_PORT,
                        (uint8_t *)&hdr, sizeof(hdr));
  if (ret < (int)sizeof(hdr))
    {
      nxmutex_unlock(&g_sdio.lock);
      return 0;  /* No data available */
    }

  /* Validate header */

  if (hdr.len == 0 || hdr.len > max_len)
    {
      nxmutex_unlock(&g_sdio.lock);
      return 0;
    }

  /* Read payload */

  pkt_len = hdr.len;
  ret = sdio_cmd53_read(1, ESP_HOSTED_IO_PORT + sizeof(hdr),
                        data, pkt_len);
  nxmutex_unlock(&g_sdio.lock);

  if (ret < pkt_len)
    {
      SDIO_ERR("SDIO recv payload failed: %d\n", ret);
      return 0;
    }

  if (channel != NULL)
    {
      *channel = hdr.channel;
    }

  return pkt_len;
}

/****************************************************************************
 * Name: esp32p4_sdio_host_write_reg
 ****************************************************************************/

int esp32p4_sdio_host_write_reg(uint32_t addr, uint8_t data)
{
  int ret;

  nxmutex_lock(&g_sdio.lock);
  ret = sdio_cmd52_write(1, addr, data, NULL);
  nxmutex_unlock(&g_sdio.lock);

  return ret;
}

/****************************************************************************
 * Name: esp32p4_sdio_host_read_reg
 ****************************************************************************/

int esp32p4_sdio_host_read_reg(uint32_t addr, uint8_t *data)
{
  int ret;

  nxmutex_lock(&g_sdio.lock);
  ret = sdio_cmd52_read(1, addr, data);
  nxmutex_unlock(&g_sdio.lock);

  return ret;
}

/****************************************************************************
 * esp32p4_wifi.c
 *
 * WiFi driver using esp_hosted protocol over SDIO.
 * ESP32-P4 (host) <-> SDIO <-> ESP32-C6 (WiFi co-processor)
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/net/netdev.h>
#include <nuttx/net/arp.h>
#include <nuttx/wqueue.h>
#include <nuttx/clock.h>
#include <nuttx/mutex.h>
#include <debug.h>
#include <errno.h>
#include <string.h>
#include <syslog.h>
#include <stdio.h>

#include "esp32p4_wifi.h"
#include "esp32p4_sdio_host.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define WIFI_TAG "wifi"
#define WIFI_ERR(...)  syslog(LOG_ERR, WIFI_TAG ": " __VA_ARGS__)
#define WIFI_INFO(...) syslog(LOG_INFO, WIFI_TAG ": " __VA_ARGS__)
#define WIFI_DBG(...)  syslog(LOG_DEBUG, WIFI_TAG ": " __VA_ARGS__)

/* esp_hosted control commands (sent over control channel) */

#define ESP_HOSTED_CMD_INIT          0x01
#define ESP_HOSTED_CMD_SCAN          0x02
#define ESP_HOSTED_CMD_CONNECT       0x03
#define ESP_HOSTED_CMD_DISCONNECT    0x04
#define ESP_HOSTED_CMD_GET_MAC       0x05
#define ESP_HOSTED_CMD_GET_STATUS    0x06

/* esp_hosted control responses */

#define ESP_HOSTED_RESP_OK           0x00
#define ESP_HOSTED_RESP_ERROR        0x01
#define ESP_HOSTED_RESP_SCAN_RESULT  0x02

/* esp_hosted control message format */

#define ESP_HOSTED_CTRL_MSG_HDR_LEN  4

/* WiFi status */

#define WIFI_STATUS_DISCONNECTED     0
#define WIFI_STATUS_CONNECTED        1

/* Work queue timing */

#define WIFI_POLL_INTERVAL   MSEC2TICK(50)
#define WIFI_CONNECT_TIMEOUT MSEC2TICK(10000)

/* Maximum scan results */

#define MAX_SCAN_RESULTS     16
#define MAX_SSID_LEN         32

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Control message header */

struct esp_hosted_ctrl_msg_s
{
  uint8_t  cmd;      /* Command type */
  uint8_t  status;   /* Response status */
  uint16_t len;      /* Payload length */
};

/* Scan result entry */

struct esp_hosted_scan_result_s
{
  uint8_t  ssid[MAX_SSID_LEN];
  uint8_t  ssid_len;
  int8_t   rssi;
  uint8_t  auth_mode;
  uint8_t  channel;
  uint8_t  bssid[6];
};

/* WiFi driver private data */

struct esp_wifi_dev_s
{
  struct net_driver_s  netdev;           /* NuttX network device */
  struct work_s        pollwork;         /* Deferred poll work */
  bool                 ifup;            /* Interface is up */
  bool                 connected;       /* WiFi connected */
  uint8_t              mac[6];          /* MAC address */
  uint8_t              rxbuf[1600];     /* Receive buffer */
  uint8_t              ctrlbuf[512];    /* Control message buffer */
  char                 ssid[MAX_SSID_LEN + 1]; /* Current SSID */
  char                 password[64];    /* Current password */
  uint8_t              status;          /* WiFi status */
  mutex_t              lock;            /* Thread safety */
  struct esp_hosted_scan_result_s scan_results[MAX_SCAN_RESULTS];
  int                  scan_count;
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int  esp_wifi_ifup(FAR struct net_driver_s *dev);
static int  esp_wifi_ifdown(FAR struct net_driver_s *dev);
static int  esp_wifi_transmit(FAR struct net_driver_s *dev);
static int  esp_wifi_txavail(FAR struct net_driver_s *dev);
static int  esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                           unsigned long arg);
static void esp_wifi_poll_work(FAR void *arg);
static int  esp_wifi_send_ctrl(uint8_t cmd, const uint8_t *data,
                               uint16_t len);
static int  esp_wifi_recv_ctrl(uint8_t *resp, uint16_t max_len);
static int  esp_wifi_do_connect(const char *ssid, const char *password);
static int  esp_wifi_do_disconnect(void);
static int  esp_wifi_do_scan(void);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct esp_wifi_dev_s g_wifi;

/****************************************************************************
 * Private Functions - Control Channel
 ****************************************************************************/

static int esp_wifi_send_ctrl(uint8_t cmd, const uint8_t *data,
                              uint16_t len)
{
  uint8_t buf[256];
  struct esp_hosted_ctrl_msg_s *msg;

  msg = (struct esp_hosted_ctrl_msg_s *)buf;
  msg->cmd    = cmd;
  msg->status = 0;
  msg->len    = len;

  if (len > 0 && data != NULL)
    {
      memcpy(buf + ESP_HOSTED_CTRL_MSG_HDR_LEN, data, len);
    }

  return esp32p4_sdio_host_send(ESP_HOSTED_CHANNEL_CTRL,
                                buf, ESP_HOSTED_CTRL_MSG_HDR_LEN + len);
}

static int esp_wifi_recv_ctrl(uint8_t *resp, uint16_t max_len)
{
  uint8_t channel;
  int ret;

  ret = esp32p4_sdio_host_recv(&channel, resp, max_len);
  if (ret > 0 && channel == ESP_HOSTED_CHANNEL_CTRL)
    {
      return ret;
    }

  return 0;
}

/****************************************************************************
 * Private Functions - WiFi Operations
 ****************************************************************************/

static int esp_wifi_do_connect(const char *ssid, const char *password)
{
  uint8_t payload[128];
  int ssid_len;
  int pwd_len;
  int ret;

  ssid_len = strlen(ssid);
  pwd_len  = strlen(password);

  if (ssid_len > MAX_SSID_LEN || pwd_len > 63)
    {
      return -EINVAL;
    }

  /* Build connect payload: ssid_len(1) + ssid + pwd_len(1) + password */

  payload[0] = (uint8_t)ssid_len;
  memcpy(payload + 1, ssid, ssid_len);
  payload[1 + ssid_len] = (uint8_t)pwd_len;
  memcpy(payload + 2 + ssid_len, password, pwd_len);

  ret = esp_wifi_send_ctrl(ESP_HOSTED_CMD_CONNECT,
                           payload, 2 + ssid_len + pwd_len);
  if (ret < 0)
    {
      WIFI_ERR("Failed to send connect command: %d\n", ret);
      return ret;
    }

  /* Wait for response */

  int timeout = 100;
  while (timeout-- > 0)
    {
      ret = esp_wifi_recv_ctrl(g_wifi.ctrlbuf, sizeof(g_wifi.ctrlbuf));
      if (ret > 0)
        {
          struct esp_hosted_ctrl_msg_s *msg =
            (struct esp_hosted_ctrl_msg_s *)g_wifi.ctrlbuf;

          if (msg->cmd == ESP_HOSTED_CMD_CONNECT)
            {
              if (msg->status == ESP_HOSTED_RESP_OK)
                {
                  WIFI_INFO("Connected to '%s'\n", ssid);
                  g_wifi.connected = true;
                  g_wifi.status = WIFI_STATUS_CONNECTED;
                  strncpy(g_wifi.ssid, ssid, MAX_SSID_LEN);
                  netdev_carrier_on(&g_wifi.netdev);
                  return OK;
                }
              else
                {
                  WIFI_ERR("Connect failed, status=%d\n", msg->status);
                  return -ECONNREFUSED;
                }
            }
        }

      up_mdelay(100);
    }

  WIFI_ERR("Connect timeout\n");
  return -ETIMEDOUT;
}

static int esp_wifi_do_disconnect(void)
{
  int ret;
  uint8_t channel;

  ret = esp_wifi_send_ctrl(ESP_HOSTED_CMD_DISCONNECT, NULL, 0);
  if (ret < 0)
    {
      return ret;
    }

  /* Wait for response */

  int timeout = 50;
  while (timeout-- > 0)
    {
      ret = esp32p4_sdio_host_recv(&channel, g_wifi.ctrlbuf,
                                   sizeof(g_wifi.ctrlbuf));
      if (ret > 0 && channel == ESP_HOSTED_CHANNEL_CTRL)
        {
          struct esp_hosted_ctrl_msg_s *msg =
            (struct esp_hosted_ctrl_msg_s *)g_wifi.ctrlbuf;

          if (msg->cmd == ESP_HOSTED_CMD_DISCONNECT &&
              msg->status == ESP_HOSTED_RESP_OK)
            {
              WIFI_INFO("Disconnected\n");
              g_wifi.connected = false;
              g_wifi.status = WIFI_STATUS_DISCONNECTED;
              memset(g_wifi.ssid, 0, sizeof(g_wifi.ssid));
              netdev_carrier_off(&g_wifi.netdev);
              return OK;
            }
        }

      up_mdelay(50);
    }

  /* Assume disconnected anyway */

  g_wifi.connected = false;
  g_wifi.status = WIFI_STATUS_DISCONNECTED;
  netdev_carrier_off(&g_wifi.netdev);
  return OK;
}

static int esp_wifi_do_scan(void)
{
  int ret;
  int timeout;

  WIFI_INFO("Starting WiFi scan\n");

  ret = esp_wifi_send_ctrl(ESP_HOSTED_CMD_SCAN, NULL, 0);
  if (ret < 0)
    {
      WIFI_ERR("Failed to send scan command: %d\n", ret);
      return ret;
    }

  g_wifi.scan_count = 0;

  /* Collect scan results */

  timeout = 200;
  while (timeout-- > 0)
    {
      uint8_t channel;
      ret = esp32p4_sdio_host_recv(&channel, g_wifi.ctrlbuf,
                                   sizeof(g_wifi.ctrlbuf));
      if (ret > 0 && channel == ESP_HOSTED_CHANNEL_CTRL)
        {
          struct esp_hosted_ctrl_msg_s *msg =
            (struct esp_hosted_ctrl_msg_s *)g_wifi.ctrlbuf;

          if (msg->cmd == ESP_HOSTED_CMD_SCAN)
            {
              if (msg->status == ESP_HOSTED_RESP_OK && msg->len == 0)
                {
                  /* Scan complete */

                  WIFI_INFO("Scan complete, %d results\n",
                            g_wifi.scan_count);
                  return OK;
                }
              else if (msg->status == ESP_HOSTED_RESP_SCAN_RESULT &&
                       msg->len > 0)
                {
                  /* Parse scan result */

                  if (g_wifi.scan_count < MAX_SCAN_RESULTS &&
                      msg->len >= sizeof(struct esp_hosted_scan_result_s))
                    {
                      memcpy(&g_wifi.scan_results[g_wifi.scan_count],
                             g_wifi.ctrlbuf + ESP_HOSTED_CTRL_MSG_HDR_LEN,
                             sizeof(struct esp_hosted_scan_result_s));
                      g_wifi.scan_count++;
                    }
                }
            }
        }

      up_mdelay(50);
    }

  WIFI_ERR("Scan timeout\n");
  return -ETIMEDOUT;
}

/****************************************************************************
 * Private Functions - Network Device Callbacks
 ****************************************************************************/

static int esp_wifi_ifup(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing up WiFi interface\n");

  priv->ifup = true;

  /* Start periodic poll work */

  work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
             priv, WIFI_POLL_INTERVAL);

  return OK;
}

static int esp_wifi_ifdown(FAR struct net_driver_s *dev)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;

  WIFI_INFO("Bringing down WiFi interface\n");

  work_cancel(LPWORK, &priv->pollwork);

  if (priv->connected)
    {
      esp_wifi_do_disconnect();
    }

  priv->ifup = false;
  return OK;
}

static int esp_wifi_transmit(FAR struct net_driver_s *dev)
{
  int ret;

  WIFI_DBG("TX %d bytes\n", dev->d_len);

  ret = esp32p4_sdio_host_send(ESP_HOSTED_CHANNEL_DATA,
                               dev->d_buf, dev->d_len);
  if (ret < 0)
    {
      WIFI_ERR("TX failed: %d\n", ret);
    }

  return ret;
}

static int esp_wifi_txavail(FAR struct net_driver_s *dev)
{
  if (dev->d_buf != NULL)
    {
      return esp_wifi_transmit(dev);
    }

  return OK;
}

static int esp_wifi_ioctl(FAR struct net_driver_s *dev, int cmd,
                          unsigned long arg)
{
  FAR struct esp_wifi_dev_s *priv =
    (FAR struct esp_wifi_dev_s *)dev->d_private;
  int ret = -ENOTTY;

  /* Handle standard wireless ioctls */

  switch (cmd)
    {
      case 0x8B19: /* SIOCSIWSCAN - Initiate scan */
        ret = esp_wifi_do_scan();
        break;

      case 0x8B1A: /* SIOCGIWSCAN - Get scan results */
        {
          /* Return scan count as the result */

          ret = priv->scan_count;
        }
        break;

      case 0x8B1B: /* SIOCSIWESSID - Set ESSID (connect) */
        {
          /* arg points to a buffer with the SSID */

          if (arg != 0)
            {
              const char *ssid = (const char *)arg;
              ret = esp_wifi_do_connect(ssid, priv->password);
            }
        }
        break;

      case 0x8B1C: /* SIOCGIWESSID - Get ESSID */
        {
          if (arg != 0)
            {
              char *buf = (char *)arg;
              strncpy(buf, priv->ssid, MAX_SSID_LEN);
              ret = OK;
            }
        }
        break;

      case 0x8B20: /* SIOCSIWAUTH - Set auth */
        ret = OK;
        break;

      case 0x8B2A: /* SIOCSIWENCODEEXT - Set key */
        {
          /* Store password for later connect */

          if (arg != 0)
            {
              const char *key = (const char *)arg;
              strncpy(priv->password, key, sizeof(priv->password) - 1);
              ret = OK;
            }
        }
        break;

      case 0x8B30: /* SIOCSIWDISPRIV - Disconnect */
        ret = esp_wifi_do_disconnect();
        break;

      default:
        WIFI_DBG("Unknown ioctl 0x%x\n", cmd);
        break;
    }

  return ret;
}

/****************************************************************************
 * Private Functions - Polling / Receive
 ****************************************************************************/

static void esp_wifi_poll_work(FAR void *arg)
{
  FAR struct esp_wifi_dev_s *priv = (FAR struct esp_wifi_dev_s *)arg;
  int ret;
  uint8_t channel;

  if (!priv->ifup)
    {
      return;
    }

  /* Try to receive data from SDIO */

  ret = esp32p4_sdio_host_recv(&channel, priv->rxbuf,
                               sizeof(priv->rxbuf));
  if (ret > 0)
    {
      if (channel == ESP_HOSTED_CHANNEL_DATA)
        {
          /* Pass received packet to the network stack */

          priv->netdev.d_buf = priv->rxbuf;
          priv->netdev.d_len = ret;

          ipv4_input(&priv->netdev);

          /* Reset buffer pointer */

          priv->netdev.d_buf = NULL;
          priv->netdev.d_len = 0;
        }
      else if (channel == ESP_HOSTED_CHANNEL_CTRL)
        {
          /* Handle control response */

          WIFI_DBG("Control response (%d bytes)\n", ret);
        }
    }

  /* Re-schedule poll work */

  if (priv->ifup)
    {
      work_queue(LPWORK, &priv->pollwork, esp_wifi_poll_work,
                 priv, WIFI_POLL_INTERVAL);
    }
}

/****************************************************************************
 * Name: esp_wifi_init_protocol
 *
 * Description:
 *   Initialize the esp_hosted protocol - handshake with ESP32-C6
 *   and get MAC address.
 *
 ****************************************************************************/

static int esp_wifi_init_protocol(void)
{
  int ret;
  int timeout;
  uint8_t channel;

  WIFI_INFO("Initializing esp_hosted protocol\n");

  /* Send init command to ESP32-C6 */

  ret = esp_wifi_send_ctrl(ESP_HOSTED_CMD_INIT, NULL, 0);
  if (ret < 0)
    {
      WIFI_ERR("Failed to send init command: %d\n", ret);
      return ret;
    }

  /* Wait for init response */

  timeout = 100;
  while (timeout-- > 0)
    {
      ret = esp32p4_sdio_host_recv(&channel, g_wifi.ctrlbuf,
                                   sizeof(g_wifi.ctrlbuf));
      if (ret > 0 && channel == ESP_HOSTED_CHANNEL_CTRL)
        {
          struct esp_hosted_ctrl_msg_s *msg =
            (struct esp_hosted_ctrl_msg_s *)g_wifi.ctrlbuf;

          if (msg->cmd == ESP_HOSTED_CMD_INIT &&
              msg->status == ESP_HOSTED_RESP_OK)
            {
              /* Extract MAC address from response if available */

              if (msg->len >= 6)
                {
                  memcpy(g_wifi.mac,
                         g_wifi.ctrlbuf + ESP_HOSTED_CTRL_MSG_HDR_LEN, 6);
                  WIFI_INFO("MAC: %02x:%02x:%02x:%02x:%02x:%02x\n",
                            g_wifi.mac[0], g_wifi.mac[1], g_wifi.mac[2],
                            g_wifi.mac[3], g_wifi.mac[4], g_wifi.mac[5]);
                }

              WIFI_INFO("esp_hosted protocol initialized\n");
              return OK;
            }
        }

      up_mdelay(50);
    }

  /* If no response, use default MAC and continue */

  WIFI_INFO("No init response, using default MAC\n");
  g_wifi.mac[0] = 0x02;
  g_wifi.mac[1] = 0x00;
  g_wifi.mac[2] = 0x00;
  g_wifi.mac[3] = 0x00;
  g_wifi.mac[4] = 0x00;
  g_wifi.mac[5] = 0x01;

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: esp32p4_wifi_init
 ****************************************************************************/

int esp32p4_wifi_init(void)
{
  int ret;

  WIFI_INFO("Initializing esp_hosted WiFi\n");

  memset(&g_wifi, 0, sizeof(g_wifi));
  nxmutex_init(&g_wifi.lock);

  /* Step 1: Initialize SDIO host */

  ret = esp32p4_sdio_host_init();
  if (ret < 0)
    {
      WIFI_ERR("SDIO host init failed: %d\n", ret);
      return ret;
    }

  /* Step 2: Initialize esp_hosted protocol */

  ret = esp_wifi_init_protocol();
  if (ret < 0)
    {
      WIFI_ERR("Protocol init failed: %d\n", ret);
      return ret;
    }

  /* Step 3: Register network device */

  g_wifi.netdev.d_ifup    = esp_wifi_ifup;
  g_wifi.netdev.d_ifdown  = esp_wifi_ifdown;
  g_wifi.netdev.d_txavail = esp_wifi_txavail;
  g_wifi.netdev.d_ioctl   = esp_wifi_ioctl;
  g_wifi.netdev.d_private = &g_wifi;

  memcpy(g_wifi.netdev.d_mac.ether.ether_addr_octet, g_wifi.mac, 6);

  ret = netdev_register(&g_wifi.netdev, NET_LL_IEEE80211);
  if (ret < 0)
    {
      WIFI_ERR("netdev_register failed: %d\n", ret);
      return ret;
    }

  WIFI_INFO("WiFi initialized, device: wlan0\n");
  return OK;
}

