106	/****************************************************************************
107	 * Private Functions - Low Level SDIO
108	 ****************************************************************************/
109	
110	/****************************************************************************
111	 * Name: sdio_send_cmd
112	 *
113	 * Description:
114	 *   Send an SDIO command and optionally read the response.
115	 *   Uses direct register access to the ESP32-P4 SDMMC peripheral.
116	 *
117	 ****************************************************************************/
118	
119	/* ESP32-P4 SDMMC register base address */
120	
121	#define SDMMC_BASE          0x50083000
122	#define SDMMC_CTRL          (SDMMC_BASE + 0x00)
123	#define SDMMC_CMD           (SDMMC_BASE + 0x04)
124	#define SDMMC_ARG           (SDMMC_BASE + 0x08)
125	#define SDMMC_RESP0         (SDMMC_BASE + 0x14)
126	#define SDMMC_STATUS        (SDMMC_BASE + 0x30)
127	#define SDMMC_RINTSTS       (SDMMC_BASE + 0x34)
128	#define SDMMC_FIFO          (SDMMC_BASE + 0x200)
129	
130	static int sdio_send_cmd(uint32_t cmd, uint32_t arg,
131	                         uint32_t *resp, int resp_type)
132	{
133	  volatile uint32_t *cmd_reg  = (volatile uint32_t *)SDMMC_CMD;
134	  volatile uint32_t *arg_reg  = (volatile uint32_t *)SDMMC_ARG;
135	  volatile uint32_t *ctrl_reg = (volatile uint32_t *)SDMMC_CTRL;
136	  volatile uint32_t *int_reg  = (volatile uint32_t *)SDMMC_RINTSTS;
137	  volatile uint32_t *rint_reg = (volatile uint32_t *)SDMMC_RINTSTS;
138	  int timeout;
139	
140	  /* Wait for controller idle */
141	
142	  timeout = SDIO_CMD_TIMEOUT_MS;
143	  while ((*ctrl_reg & 0x80000000) && timeout-- > 0)
144	    {
145	      up_mdelay(1);
146	    }
147	
148	  if (timeout <= 0)
149	    {
150	      SDIO_ERR("Controller busy\n");
151	      return -ETIMEDOUT;
152	    }
153	
154	  /* Clear pending interrupts */
155	
156	  *int_reg = 0xFFFFFFFF;
157	
158	  /* Set argument */
159	
160	  *arg_reg = arg;
161	
162	  /* Build command register value */
163	
164	  uint32_t cmd_val = cmd & 0x3F;
165	
166	  /* Set response type */
167	
168	  switch (resp_type)
169	    {
170	      case SDIO_RESP_R4:
171	      case SDIO_RESP_R6:
172	        cmd_val |= (1 << 6);  /* Response expected */
173	        cmd_val |= (1 << 7);  /* Check response CRC */
174	        break;
175	      default:
176	        break;
177	    }
178	
179	  cmd_val |= (1 << 13);  /* Wait for data complete */
180	  cmd_val |= (1 << 10);  /* Send initialization sequence if CMD0 */
181	  cmd_val |= (1 << 31);  /* Start command */
182	
183	  *cmd_reg = cmd_val;
184	
185	  /* Wait for command done */
186	
187	  timeout = SDIO_CMD_TIMEOUT_MS;
188	  while (!(*rint_reg & 0x4) && timeout-- > 0)
189	    {
190	      up_mdelay(1);
191	    }
192	
193	  if (timeout <= 0)
194	    {
195	      SDIO_ERR("CMD%lu timeout\n", (unsigned long)cmd);
196	      return -ETIMEDOUT;
197	    }
198	
199	  /* Check for errors */
200	
201	  if (*rint_reg & 0x2)
202	    {
203	      SDIO_ERR("CMD%lu response error\n", (unsigned long)cmd);
204	      return -EIO;
205	    }
206	
207	  if (*rint_reg & 0x100)
208	    {
209	      SDIO_ERR("CMD%lu response timeout\n", (unsigned long)cmd);
210	      return -ETIMEDOUT;
211	    }
212	
213	  /* Read response if requested */
214	
215	  if (resp != NULL && resp_type != SDIO_RESP_NONE)
216	    {
217	      *resp = *((volatile uint32_t *)SDMMC_RESP0);
218	    }
219	
220	  return OK;
221	}
