223	/****************************************************************************
224	 * Name: sdio_cmd52_read
225	 *
226	 * Description:
227	 *   CMD52 - IO Read Direct (single byte)
228	 *
229	 ****************************************************************************/
230	
231	static int sdio_cmd52_read(uint8_t func, uint32_t addr, uint8_t *data)
232	{
233	  uint32_t arg;
234	  uint32_t resp;
235	  int ret;
236	
237	  arg = CMD52_FUNC(func) | CMD52_REG_ADDR(addr);
238	
239	  ret = sdio_send_cmd(SDIO_CMD_IO_RW_DIRECT, arg, &resp, SDIO_RESP_R4);
240	  if (ret < 0)
241	    {
242	      return ret;
243	    }
244	
245	  if (data != NULL)
246	    {
247	      *data = (resp >> 8) & 0xFF;
248	    }
249	
250	  return OK;
251	}
