261	static int sdio_cmd52_write(uint8_t func, uint32_t addr, uint8_t data,
262	                            uint8_t *resp_data)
263	{
264	  uint32_t arg;
265	  uint32_t resp;
266	  int ret;
267	
268	  arg = CMD52_OP_WRITE | CMD52_FUNC(func) | CMD52_REG_ADDR(addr) | data;
269	
270	  ret = sdio_send_cmd(SDIO_CMD_IO_RW_DIRECT, arg, &resp, SDIO_RESP_R4);
271	  if (ret < 0)
272	    {
273	      return ret;
274	    }
275	
276	  if (resp_data != NULL)
277	    {
278	      *resp_data = (resp >> 8) & 0xFF;
279	    }
