284	/****************************************************************************
285	 * Name: sdio_cmd53_read
286	 *
287	 * Description:
288	 *   CMD53 - IO Read Extended (block transfer)
289	 *
290	 ****************************************************************************/
291	
292	static int sdio_cmd53_read(uint8_t func, uint32_t addr,
293	                           uint8_t *buf, uint16_t count)
294	{
295	  uint32_t arg;
296	  uint32_t resp;
297	  int ret;
298	  int i;
299	
300	  /* For simplicity, use byte mode (not block mode) */
301	
302	  arg = CMD53_FUNC(func) | CMD53_REG_ADDR(addr) | CMD53_COUNT(count);
303	
304	  ret = sdio_send_cmd(SDIO_CMD_IO_RW_EXTENDED, arg, &resp, SDIO_RESP_R4);
305	  if (ret < 0)
306	    {
307	      return ret;
308	    }
309	
310	  /* Read data from FIFO */
311	
312	  volatile uint32_t *fifo = (volatile uint32_t *)SDMMC_FIFO;
313	
314	  for (i = 0; i < (count + 3) / 4; i++)
315	    {
316	      uint32_t word = *fifo;
317	      int j;
318	      for (j = 0; j < 4 && (i * 4 + j) < count; j++)
319	        {
320	          buf[i * 4 + j] = (word >> (j * 8)) & 0xFF;
321	        }
322	    }
323	
324	  return count;
325	}
326	
327	/****************************************************************************
328	 * Name: sdio_cmd53_write
329	 *
330	 * Description:
331	 *   CMD53 - IO Write Extended (block transfer)
332	 *
333	 ****************************************************************************/
334	
335	static int sdio_cmd53_write(uint8_t func, uint32_t addr,
336	                            const uint8_t *buf, uint16_t count)
337	{
338	  uint32_t arg;
339	  uint32_t resp;
340	  int ret;
341	  int i;
342	
343	  arg = CMD53_OP_WRITE | CMD53_FUNC(func) |
344	        CMD53_REG_ADDR(addr) | CMD53_COUNT(count);
345	
346	  /* Write data to FIFO */
347	
348	  volatile uint32_t *fifo = (volatile uint32_t *)SDMMC_FIFO;
349	
350	  for (i = 0; i < (count + 3) / 4; i++)
351	    {
352	      uint32_t word = 0;
353	      int j;
354	      for (j = 0; j < 4 && (i * 4 + j) < count; j++)
355	        {
356	          word |= ((uint32_t)buf[i * 4 + j]) << (j * 8);
357	        }
358	      *fifo = word;
359	    }
360	
361	  ret = sdio_send_cmd(SDIO_CMD_IO_RW_EXTENDED, arg, &resp, SDIO_RESP_R4);
362	  if (ret < 0)
363	    {
364	      return ret;
365	    }
366	
367	  return count;
368	}
