370	/****************************************************************************
371	 * Name: sdio_init_hw
372	 *
373	 * Description:
374	 *   Initialize the ESP32-P4 SDMMC hardware for SDIO communication.
375	 *
376	 ****************************************************************************/
377	
378	static int sdio_init_hw(void)
379	{
380	  volatile uint32_t *clk_rst_reg;
381	  int timeout;
382	  uint32_t resp;
383	  int ret;
384	
385	  up_puts("SDIO: init_hw start\n");
386	
387	  /* Step 1: Enable SDMMC peripheral clock
388	   * ESP32-P4: HP_SYS_CLKRST_BASE = 0x500E6000
389	   * soc_clk_ctrl1 is at offset 0x04
390	   */
391	
392	  clk_rst_reg = (volatile uint32_t *)0x500E6004;
393	  *clk_rst_reg |= (1 << 12);  /* Enable SDMMC clock */
394	  up_puts("SDIO: clock enabled\n");
395	
396	  /* Step 2: Configure GPIO pins for SDIO2
397	   * User-provided pin mapping:
398	   *   SD2 D0  = GPIO14
399	   *   SD2 D1  = GPIO15
400	   *   SD2 D2  = GPIO16
401	   *   SD2 D3  = GPIO17
402	   *   SD2 CLK = GPIO18
403	   *   SD2 CMD = GPIO19
404	   *
405	   * GPIO matrix routing is needed for SLOT1 (SLOT0 uses IOMUX GPIO39-48).
406	   * TODO: Configure GPIO matrix registers to route these pins to SDMMC SLOT1.
407	   */
408	
409	  /* Step 3: Reset the SDMMC controller */
410	
411	  volatile uint32_t *ctrl = (volatile uint32_t *)SDMMC_CTRL;
412	  *ctrl = 0x1;  /* Software reset */
413	  up_mdelay(10);
414	  up_puts("SDIO: controller reset done\n");
415	
416	  /* Step 4: Set clock to identification mode (400kHz) */
417	
418	  /* TODO: Configure clock divider for 400kHz */
419	
420	  /* Step 5: Send CMD0 (GO_IDLE_STATE) */
421	
422	  ret = sdio_send_cmd(SDIO_CMD_GO_IDLE_STATE, 0, NULL, SDIO_RESP_NONE);
423	  up_puts("SDIO: CMD0 done\n");
424	  if (ret < 0)
425	    {
426	      return ret;
427	    }
428	
429	  up_mdelay(10);
430	
431	  /* Step 6: Send CMD5 (IO_SEND_OP_COND) to detect SDIO card
432	   * Repeat until card is ready
433	   */
434	
435	  timeout = SDIO_INIT_TIMEOUT_MS;
436	  while (timeout-- > 0)
437	    {
438	      /* CMD5 with arg=0 to query voltage window */
439	
440	      ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0, &resp, SDIO_RESP_R4);
441	      if (ret < 0)
442	        {
443	          up_mdelay(1);
444	          continue;
445	        }
446	
447	      /* Check if card is ready (bit 31 of R4) */
448	
449	      if (resp & (1 << 31))
450	        {
451	          SDIO_INFO("SDIO card ready, OCR=0x%08lx\n", (unsigned long)resp);
452	          break;
453	        }
454	
455	      /* Send CMD5 with voltage window to power up card */
456	
457	      ret = sdio_send_cmd(SDIO_CMD_SEND_OP_COND, 0x00FF8000,
458	                          &resp, SDIO_RESP_R4);
459	      up_mdelay(10);
460	    }
461	
462	  if (timeout <= 0)
463	    {
464	      SDIO_ERR("SDIO card not ready\n");
465	      return -ETIMEDOUT;
466	    }
467	
468	  /* Step 7: Send CMD3 (SEND_RELATIVE_ADDR) to get RCA */
469	
470	  ret = sdio_send_cmd(SDIO_CMD_SEND_RELATIVE_ADDR, 0, &resp, SDIO_RESP_R6);
471	  if (ret < 0)
472	    {
473	      SDIO_ERR("CMD3 failed: %d\n", ret);
474	      return ret;
475	    }
476	
477	  g_sdio.rca = (resp >> 16) & 0xFFFF;
478	  SDIO_INFO("SDIO RCA=0x%04x\n", g_sdio.rca);
479	
480	  /* Step 8: Send CMD7 (SELECT_CARD) to select the card */
481	
482	  ret = sdio_send_cmd(SDIO_CMD_SELECT_CARD,
483	                      ((uint32_t)g_sdio.rca) << 16,
484	                      &resp, SDIO_RESP_R6);
485	  if (ret < 0)
486	    {
487	      SDIO_ERR("CMD7 failed: %d\n", ret);
488	      return ret;
489	    }
490	
491	  SDIO_INFO("SDIO card selected\n");
492	
493	  /* Step 9: Enable SDIO function 1 (used by esp_hosted) */
494	
495	  ret = sdio_cmd52_write(0, SDIO_CCCR_IO_ENABLE, 0x02, NULL);
496	  if (ret < 0)
497	    {
498	      SDIO_ERR("Failed to enable SDIO function 1: %d\n", ret);
499	      return ret;
500	    }
501	
502	  /* Wait for function 1 to be ready */
503	
504	  timeout = SDIO_CMD_TIMEOUT_MS;
505	  while (timeout-- > 0)
506	    {
507	      uint8_t ready;
508	      ret = sdio_cmd52_read(0, SDIO_CCCR_IO_READY, &ready);
509	      if (ret >= 0 && (ready & 0x02))
510	        {
511	          SDIO_INFO("SDIO function 1 ready\n");
512	          break;
513	        }
514	      up_mdelay(1);
515	    }
516	
517	  if (timeout <= 0)
518	    {
519	      SDIO_ERR("SDIO function 1 not ready\n");
520	      return -ETIMEDOUT;
521	    }
522	
523	  /* Step 10: Set bus width to 4-bit */
524	
525	  ret = sdio_cmd52_write(0, SDIO_CCCR_BUS_CTRL, 0x02, NULL);
526	  if (ret < 0)
527	    {
528	      SDIO_ERR("Failed to set 4-bit bus width: %d\n", ret);
529	      /* Not fatal, continue with 1-bit mode */
530	    }
531	  else
532	    {
533	      SDIO_INFO("4-bit bus width enabled\n");
534	    }
535	
536	  /* Step 11: Increase clock speed to operational frequency */
537	
538	  /* TODO: Set clock to CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ */
539	
540	  up_puts("SDIO: init complete\n");
541	  return OK;
542	}
