552	int esp32p4_sdio_host_init(void)
553	{
554	  int ret;
555	
556	  memset(&g_sdio, 0, sizeof(g_sdio));
557	  nxmutex_init(&g_sdio.lock);
558	
559	  g_sdio.bus_num       = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_BUS;
560	  g_sdio.freq          = CONFIG_ESP32P4_WIFI_HOSTED_SDIO_FREQ;
561	  g_sdio.gpio_data_rdy = CONFIG_ESP32P4_WIFI_HOSTED_GPIO_DATA_RDY;
562	
563	  /* Initialize SDIO hardware */
564	
565	  ret = sdio_init_hw();
566	  if (ret < 0)
567	    {
568	      SDIO_ERR("SDIO hardware init failed: %d\n", ret);
569	      return ret;
570	    }
