576	/****************************************************************************
577	 * Name: esp32p4_sdio_host_send
578	 ****************************************************************************/
579	
580	int esp32p4_sdio_host_send(uint8_t channel, const uint8_t *data,
581	                           uint16_t len)
582	{
583	  struct esp_hosted_header_s hdr;
584	  uint8_t *pkt;
585	  int ret;
586	
587	  if (!g_sdio.initialized)
588	    {
589	      return -ENODEV;
590	    }
591	
592	  /* Build esp_hosted packet */
593	
594	  hdr.channel  = channel;
595	  hdr.reserved = 0;
596	  hdr.len      = len;
597	  hdr.offset   = sizeof(hdr);
598	  hdr.checksum = channel + len;
599	
600	  /* Copy header + data to buffer */
601	
602	  pkt = g_sdio.buffer;
603	  memcpy(pkt, &hdr, sizeof(hdr));
604	  memcpy(pkt + sizeof(hdr), data, len);
605	
606	  nxmutex_lock(&g_sdio.lock);
607	
608	  /* Write to SDIO function 1 */
609	
610	  ret = sdio_cmd53_write(1, ESP_HOSTED_IO_PORT,
611	                         pkt, sizeof(hdr) + len);
612	
613	  nxmutex_unlock(&g_sdio.lock);
614	
615	  if (ret < 0)
616	    {
617	      SDIO_ERR("SDIO send failed: %d\n", ret);
618	      return ret;
619	    }
620	
621	  return OK;
622	}
623	
624	/****************************************************************************
625	 * Name: esp32p4_sdio_host_recv
626	 ****************************************************************************/
627	
628	int esp32p4_sdio_host_recv(uint8_t *channel, uint8_t *data,
629	                           uint16_t max_len)
630	{
631	  struct esp_hosted_header_s hdr;
632	  int ret;
633	  int pkt_len;
634	
635	  if (!g_sdio.initialized)
636	    {
637	      return -ENODEV;
638	    }
639	
640	  nxmutex_lock(&g_sdio.lock);
641	
642	  /* Read header first (8 bytes) */
643	
644	  ret = sdio_cmd53_read(1, ESP_HOSTED_IO_PORT,
645	                        (uint8_t *)&hdr, sizeof(hdr));
646	  if (ret < (int)sizeof(hdr))
647	    {
648	      nxmutex_unlock(&g_sdio.lock);
649	      return 0;  /* No data available */
650	    }
651	
652	  /* Validate header */
653	
654	  if (hdr.len == 0 || hdr.len > max_len)
655	    {
656	      nxmutex_unlock(&g_sdio.lock);
657	      return 0;
658	    }
659	
660	  /* Read payload */
661	
662	  pkt_len = hdr.len;
663	  ret = sdio_cmd53_read(1, ESP_HOSTED_IO_PORT + sizeof(hdr),
664	                        data, pkt_len);
665	  nxmutex_unlock(&g_sdio.lock);
666	
667	  if (ret < pkt_len)
668	    {
669	      SDIO_ERR("SDIO recv payload failed: %d\n", ret);
670	      return 0;
