static int sdio_send_cmd(uint32_t cmd, uint32_t arg,
                         uint32_t *resp, int resp_type)
{
  volatile uint32_t *cmd_reg  = (volatile uint32_t *)SDMMC_CMD;
  volatile uint32_t *arg_reg  = (volatile uint32_t *)SDMMC_ARG;
  volatile uint32_t *ctrl_reg = (volatile uint32_t *)SDMMC_CTRL;
  volatile uint32_t *int_reg  = (volatile uint32_t *)SDMMC_RINTSTS;
  volatile uint32_t *rint_reg = (volatile uint32_t *)SDMMC_RINTSTS;
  int timeout;

  /* Wait for controller idle */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while ((*ctrl_reg & 0x80000000) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      SDIO_ERR("Controller busy\n");
      return -ETIMEDOUT;
    }

  /* Clear pending interrupts */

  *int_reg = 0xFFFFFFFF;

  /* Set argument */

  *arg_reg = arg;

  /* Build command register value */

  uint32_t cmd_val = cmd & 0x3F;

  /* Set response type */

  switch (resp_type)
    {
      case SDIO_RESP_R4:
      case SDIO_RESP_R6:
        cmd_val |= (1 << 6);  /* Response expected */
        cmd_val |= (1 << 7);  /* Check response CRC */
        break;
      default:
        break;
    }

  cmd_val |= (1 << 13);  /* Wait for data complete */
  cmd_val |= (1 << 10);  /* Send initialization sequence if CMD0 */
  cmd_val |= (1 << 31);  /* Start command */

  *cmd_reg = cmd_val;

  /* Wait for command done */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while (!(*rint_reg & 0x4) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      SDIO_ERR("CMD%lu timeout\n", (unsigned long)cmd);
      return -ETIMEDOUT;
    }

  /* Check for errors */

  if (*rint_reg & 0x2)
    {
      SDIO_ERR("CMD%lu response error\n", (unsigned long)cmd);
      return -EIO;
    }

  if (*rint_reg & 0x100)
    {
      SDIO_ERR("CMD%lu response timeout\n", (unsigned long)cmd);
      return -ETIMEDOUT;
    }

  /* Read response if requested */

  if (resp != NULL && resp_type != SDIO_RESP_NONE)
    {
      *resp = *((volatile uint32_t *)SDMMC_RESP0);
    }

  return OK;
}

