static int sdio_send_cmd(uint32_t cmd, uint32_t arg,
                         uint32_t *resp, int resp_type)
{
  volatile uint32_t *cmd_reg  = (volatile uint32_t *)SDMMC_CMD;
  volatile uint32_t *arg_reg  = (volatile uint32_t *)SDMMC_CMDARG;
  volatile uint32_t *rint_reg = (volatile uint32_t *)SDMMC_RINTSTS;
  volatile uint32_t *status   = (volatile uint32_t *)SDMMC_STATUS;
  int timeout;

  /* Wait for controller not busy (data state machine idle) */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while ((*status & (1 << 9)) && timeout-- > 0)  /* bit 9: data busy */
    {
      up_mdelay(1);
    }

  /* Clear pending interrupts */

  *rint_reg = 0xFFFFFFFF;

  /* Set argument */

  *arg_reg = arg;

  /* Build command register value
   * Bits [5:0]   = command index
   * Bit  [6]     = response expected
   * Bit  [7]     = check response CRC
   * Bit  [8]     = data expected (for CMD53)
   * Bit  [9]     = read/write (1=write)
   * Bit  [10]    = send initialization sequence
   * Bit  [13]    = wait for data complete
   * Bit  [21]    = stop abort command
   * Bit  [31]    = start command (CI)
   */

  uint32_t cmd_val = (cmd & 0x3F) | (1 << 31);  /* cmd index + start */

  /* Set response type */

  switch (resp_type)
    {
      case SDIO_RESP_R4:
        cmd_val |= (1 << 6);   /* Response expected */
        break;
      case SDIO_RESP_R6:
        cmd_val |= (1 << 6);   /* Response expected */
        cmd_val |= (1 << 7);   /* Check response CRC */
        break;
      default:
        break;
    }

  /* For CMD0, send initialization sequence */

  if (cmd == 0)
    {
      cmd_val |= (1 << 10);
    }

  *cmd_reg = cmd_val;

  /* Wait for command done (CI bit clears, or command done interrupt) */

  timeout = SDIO_CMD_TIMEOUT_MS;
  while ((*cmd_reg & (1 << 31)) && timeout-- > 0)
    {
      up_mdelay(1);
    }

  if (timeout <= 0)
    {
      up_puts("SDIO: CMD timeout\n");
      return -ETIMEDOUT;
    }

  /* Check raw interrupt status for errors */

  uint32_t rint = *rint_reg;

  if (rint & (1 << 1))  /* Response error */
    {
      up_puts("SDIO: CMD resp error\n");
      *rint_reg = (1 << 1);
      return -EIO;
    }

  if (rint & (1 << 8))  /* Response timeout */
    {
      up_puts("SDIO: CMD resp timeout\n");
      *rint_reg = (1 << 8);
      return -ETIMEDOUT;
    }

  if (rint & (1 << 2))  /* Command done */
    {
      *rint_reg = (1 << 2);  /* Clear interrupt */
    }

  /* Read response if requested */

  if (resp != NULL && resp_type != SDIO_RESP_NONE)
    {
      *resp = *((volatile uint32_t *)SDMMC_RESP0);
    }

  return OK;
}

